def set_quota (s : State) (key : String) (tokens : Nat) : Except String (Nat × State) :=
  if key = "" then .error "key must be non-empty"
  else if s.used key > tokens then .error "quota is below the key's current usage"
  else .ok (tokens, { s with quotas := (key, tokens) :: s.quotas.filter (fun x => !(x.1 == key)) })

